style.css:
@-moz-document domain("roblox.com/home") {
body {
    background: url("https://scontent-dfw5-2.xx.fbcdn.net/v/t1.15752-9/494356926_1068983021758827_7492171097603894594_n.jpg?stp=dst-jpg_p480x480_tt6&_nc_cat=100&ccb=1-7&_nc_sid=0024fc&_nc_ohc=DAy4MiPhbUwQ7kNvwE3qHtu&_nc_oc=Adm0WV0FLFft-7634LR0RonbaxgN8LV8l9bxTBnWozQWcToqPIpviz1Q_M02JqWNYgA&_nc_ad=z-m&_nc_cid=0&_nc_zt=23&_nc_ht=scontent-dfw5-2.xx&oh=03_Q7cD2QH7Jc1sQw_CVma4peJeDoInf1P-DWaDN4UXzLwzrKlFPA&oe=68462948") 
                no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
    font-family: 'Segoe UI', sans-serif !important;
  }

  .container-main,
  .rbx-header,
  .footer,
  .content,
  .navbar,
  .modal-content,
  .section-content {
    background-color: rgba(0, 0, 0, 0) !important;
    border: none !important;
  }

  a,
  .text-link {
    color: #9dcaff !important;
  }

  .btn-primary {
    background-color: #4c84ff !important;
    border-color: #4c84ff !important;
  }

  .ad-container,
  .promo-banner {
    display: none !important;
  }
}
